import pytest

def split_bill(total_cents, people):
    if people <= 0:
        raise ValueError('people must be positive')
    share, extra = divmod(total_cents, people)
    return [share + 1] * extra + [share] * (people - extra)

@pytest.mark.parametrize('total, people, expected', [
    (900, 3, [300, 300, 300]),   # happy path
    (1000, 3, [334, 333, 333]),  # remainder goes somewhere
    (0, 2, [0, 0]),              # zero
    (5, 1, [5]),                 # single
])
def test_split_bill(total, people, expected):
    result = split_bill(total, people)       # act
    assert result == expected                # assert
    assert sum(result) == total              # invariant: no cent lost

def test_rejects_no_people():
    with pytest.raises(ValueError, match='positive'):
        split_bill(100, 0)

