import time

def count_recent(timestamps, window, now=None):
    if now is None:
        now = time.time()
    start = now - window
    return sum(1 for t in timestamps if start < t <= now)

def fixture_log(fixtures, tests):
    log = []
    session_ready = []

    for test in tests:
        test_ready = []

        def ensure(name):
            spec = fixtures[name]
            ready = session_ready if spec["scope"] == "session" else test_ready
            if name in ready:
                return
            for dep in spec["deps"]:
                ensure(dep)
            log.append(f"setup {name}")
            ready.append(name)

        for name in test["uses"]:
            ensure(name)
        log.append(f"run {test['name']}")
        log.extend(f"teardown {name}" for name in reversed(test_ready))

    log.extend(f"teardown {name}" for name in reversed(session_ready))
    return log

